package pprof.spark.bench.synthetic

/** Counter-based draws for synthetic data (scale-test plan §2 and §4). Every value is a function of the seed, an
  * identifier (a row's or a provider's), a stream and a draw number alone, through SplitMix64's finalizer, as the
  * bootstrap's draws are (STAT-2). Data are therefore the same on any cluster, partitioning and order, and any row
  * can be regenerated by itself.
  */
object Draws {

  private val Golden = 0x9e3779b97f4a7c15L
  private val Step = 1.0 / (1L << 53).toDouble

  /** SplitMix64's finalizer (Steele, Lea and Flood, 2014). */
  def mix(x: Long): Long = {
    var z = x + Golden
    z = (z ^ (z >>> 30)) * 0xbf58476d1ce4e5b9L
    z = (z ^ (z >>> 27)) * 0x94d049bb133111ebL
    z ^ (z >>> 31)
  }

  /** 64 random bits for (seed, identifier, stream, draw). */
  def bits(seed: Long, id: Long, stream: Int, draw: Int): Long =
    mix(mix(mix(mix(seed + Golden) ^ id) ^ stream.toLong) ^ draw.toLong)

  /** A uniform in (0, 1): the 53 high bits, offset by half a step, so that neither 0 nor 1 occurs. */
  def uniform(seed: Long, id: Long, stream: Int, draw: Int = 0): Double =
    ((bits(seed, id, stream, draw) >>> 11).toDouble + 0.5) * Step

  /** A standard normal by Box–Muller from the stream's draws 2k and 2k + 1, with `StrictMath`, whose results are
    * the same on every JVM.
    */
  def normal(seed: Long, id: Long, stream: Int, draw: Int = 0): Double = {
    val u1 = uniform(seed, id, stream, 2 * draw)
    val u2 = uniform(seed, id, stream, 2 * draw + 1)
    StrictMath.sqrt(-2.0 * StrictMath.log(u1)) * StrictMath.cos(2.0 * StrictMath.PI * u2)
  }
}
